"""
TILAKINO CINEMA - Telegram kino boti (BITTA FAYL, Pydroid 3 uchun)

O'rnatish (Pydroid 3 -> menyu -> Pip):  requests   va (sayt kerak bo'lsa)  flask
Ishga tushirish: pastdagi SOZLAMALAR ni to'ldiring va  ▶ tugmasini bosing.

Bot "polling" rejimida ishlaydi (webhook/Render kerak emas) - telefoningiz ishlab turganda bot ishlaydi.
Ma'lumotlar shu fayl yonidagi tilakino.db (SQLite) faylida saqlanadi.
Admin: /admin  (faqat ADMIN_ID dagi raqamli Telegram ID).
"""
import os
import sys
import types
TOKEN = ''  # Token faqat Render Environment Variables orqali beriladi
ADMIN_ID = 6359925487
BOT_USERNAME = ''
ANIMATIONS = False
RUN_SITE = True
SITE_PORT = int(os.environ.get('PORT', '10000'))
HELP_ADMIN_USERNAMES = ''
PUBLIC_SITE_URL = ''
DB_FILE = 'tilakino.db'
_HERE = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()

def _setenv(k, v):
    if not os.environ.get(k) and v not in (None, ''):
        os.environ[k] = str(v)
_setenv('TELEGRAM_BOT_TOKEN', TOKEN)
_setenv('WEBHOOK_SECRET', 'polling-mode')
_setenv('ADMIN_ID', ADMIN_ID)
_setenv('BOT_USERNAME', BOT_USERNAME)
_setenv('HELP_ADMIN_USERNAMES', HELP_ADMIN_USERNAMES)
_setenv('RENDER_EXTERNAL_URL', PUBLIC_SITE_URL)
_setenv('ANIMATIONS', '0')
_setenv('ANIM_DELAY', '0')
_setenv('DATABASE_URL', 'sqlite:///' + os.path.join(_HERE, DB_FILE))
# Render webhook boot: TILAKINO_NO_BOOT ataylab o'rnatilmaydi
_setenv('ENABLE_SCHEDULER', '1')
_SOURCES = {}
_TEMPLATES = {}
_SOURCES['config'] = '# -*- coding: utf-8 -*-\n"""Sozlamalar: barcha sirlar faqat muhit o\'zgaruvchilaridan o\'qiladi."""\nimport os\nimport re\n\nDEFAULT_ADMIN_ID = 6359925487\n\n\ndef _g(name, default=""):\n    return (os.environ.get(name) or default).strip()\n\n\nclass Settings:\n    def __init__(self):\n        self.reload()\n\n    def reload(self):\n        self.token = _g("TELEGRAM_BOT_TOKEN")\n        self.webhook_secret = _g("WEBHOOK_SECRET")\n        self.base_url = _g("RENDER_EXTERNAL_URL").rstrip("/")\n        self.bot_username = _g("BOT_USERNAME").lstrip("@")\n        self.help_admin_usernames = _g("HELP_ADMIN_USERNAMES", "")\n        self.database_url = _g("DATABASE_URL", "sqlite:///tilakino.db")\n        self.cron_secret = _g("CRON_SECRET")\n        self.payment_secret = _g("PAYMENT_CALLBACK_SECRET")\n        self.animations = False  # animatsiyalar toliq ochirilgan\n        self.anim_delay = 0.0\n        # "Yuklanmoqda" faqat javob SPIN_AFTER soniyadan kech kelsa ko\'rsatiladi (tez javobga qo\'shimcha kutish yo\'q).\n        # 0 = har doim darhol ko\'rsatish.\n        self.spin_after = -1.0\n        self.scheduler = _g("ENABLE_SCHEDULER", "1") not in ("0", "false", "no")\n        self.tz = "Asia/Tashkent"\n        raw = _g("ADMIN_ID", str(DEFAULT_ADMIN_ID))\n        self._admin_raw = raw\n        self.admin_id = int(raw) if raw.lstrip("-").isdigit() else DEFAULT_ADMIN_ID\n\n    def problems(self):\n        """Ishga tushishga to\'sqinlik qiladigan sozlama kamchiliklari."""\n        out = []\n        if not self.token:\n            out.append("TELEGRAM_BOT_TOKEN o\'rnatilmagan")\n        if not self.webhook_secret:\n            out.append("WEBHOOK_SECRET o\'rnatilmagan")\n        elif not re.fullmatch(r"[A-Za-z0-9_-]{1,256}", self.webhook_secret):\n            out.append("WEBHOOK_SECRET faqat A-Z a-z 0-9 _ - belgilaridan iborat bo\'lishi kerak")\n        if not self._admin_raw.lstrip("-").isdigit():\n            out.append("ADMIN_ID raqam emas, standart qiymat ishlatilmoqda")\n        return out\n\n    def warnings(self):\n        out = []\n        if self.database_url.startswith("sqlite"):\n            out.append("SQLite ishlatilmoqda: Render bepul rejasida fayl tizimi vaqtinchalik, "\n                       "ma\'lumotlar qayta ishga tushganda yo\'qoladi. DATABASE_URL (PostgreSQL) bering.")\n        if not self.base_url:\n            out.append("RENDER_EXTERNAL_URL yo\'q: webhook avtomatik o\'rnatilmaydi")\n        return out\n\n\ncfg = Settings()\n'
_SOURCES['db'] = '# -*- coding: utf-8 -*-\n"""Yengil DB qatlami: SQLite (dev/test) va PostgreSQL (production, psycopg2).\nSQL \'?\' belgili yoziladi, PostgreSQL uchun avtomatik \'%s\' ga o\'giriladi.\nVaqt: UTC epoch (butun son). Foydalanuvchiga ko\'rsatishda Asia/Tashkent."""\nimport contextlib\nimport sqlite3\nimport threading\n\nfrom config import cfg\n\nIS_PG = False\n_url = None\n_lock = threading.Lock()\n_tl = threading.local()      # har bir thread uchun doimiy ulanish (har so\'rovda qayta ochilmaydi)\n_init_hooks = []             # db.init() chaqirilganda keshlarni tozalash uchun\n\nSCHEMA_VERSION = 3\n\n_DDL = [\n    """CREATE TABLE IF NOT EXISTS users(\n        id BIGINT PRIMARY KEY, first_name TEXT, username TEXT, lang TEXT DEFAULT \'uz\',\n        joined_at BIGINT, last_seen BIGINT, blocked INTEGER DEFAULT 0, bot_blocked INTEGER DEFAULT 0,\n        premium_until BIGINT DEFAULT 0, remind3_for BIGINT DEFAULT 0, remind0_for BIGINT DEFAULT 0,\n        referrer_id BIGINT, ref_count INTEGER DEFAULT 0, last_sponsor_at BIGINT DEFAULT 0, notify_new INTEGER DEFAULT 0,\n        streak INTEGER DEFAULT 0, last_checkin TEXT, blocked_until BIGINT DEFAULT 0, remind_off INTEGER DEFAULT 0)""",\n    """CREATE TABLE IF NOT EXISTS movies(\n        id {PK}, code TEXT NOT NULL UNIQUE, kind TEXT NOT NULL DEFAULT \'movie\', title TEXT NOT NULL,\n        poster_file_id TEXT, year INTEGER, country TEXT, genre TEXT, language TEXT, description TEXT,\n        rating REAL, published INTEGER DEFAULT 1, views INTEGER DEFAULT 0, created_at BIGINT,\n        trailer_url TEXT, featured INTEGER DEFAULT 0)""",\n    """CREATE TABLE IF NOT EXISTS episodes(\n        id {PK}, series_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        season INTEGER NOT NULL DEFAULT 1, number INTEGER NOT NULL, title TEXT, description TEXT,\n        published INTEGER DEFAULT 1, views INTEGER DEFAULT 0, created_at BIGINT,\n        UNIQUE(series_id, season, number))""",\n    """CREATE TABLE IF NOT EXISTS video_variants(\n        id {PK}, movie_id INTEGER REFERENCES movies(id) ON DELETE CASCADE,\n        episode_id INTEGER REFERENCES episodes(id) ON DELETE CASCADE,\n        quality TEXT NOT NULL, label TEXT, file_id TEXT, ftype TEXT, external_url TEXT, created_at BIGINT,\n        UNIQUE(movie_id, quality), UNIQUE(episode_id, quality))""",\n    """CREATE TABLE IF NOT EXISTS favorites(\n        user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        created_at BIGINT, PRIMARY KEY(user_id, movie_id))""",\n    """CREATE TABLE IF NOT EXISTS history(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        episode_id INTEGER REFERENCES episodes(id) ON DELETE CASCADE, watched_at BIGINT)""",\n    """CREATE TABLE IF NOT EXISTS payments(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id), plan_key TEXT, days INTEGER, amount INTEGER,\n        status TEXT NOT NULL DEFAULT \'pending\', reference TEXT NOT NULL UNIQUE, proof_file_id TEXT,\n        provider TEXT, provider_txn TEXT UNIQUE, created_at BIGINT, decided_at BIGINT, decided_by BIGINT)""",\n    """CREATE TABLE IF NOT EXISTS subscriptions(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id), days INTEGER, starts_at BIGINT,\n        expires_at BIGINT, source TEXT, payment_id INTEGER UNIQUE REFERENCES payments(id), active INTEGER DEFAULT 1)""",\n    """CREATE TABLE IF NOT EXISTS admins(\n        user_id BIGINT PRIMARY KEY, role TEXT, perms TEXT, added_by BIGINT, added_at BIGINT)""",\n    "CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT)",\n    """CREATE TABLE IF NOT EXISTS sponsors(\n        id {PK}, text TEXT NOT NULL, url TEXT, enabled INTEGER DEFAULT 1, created_at BIGINT)""",\n    """CREATE TABLE IF NOT EXISTS broadcasts(\n        id {PK}, admin_id BIGINT, src_chat BIGINT, src_msg BIGINT, status TEXT DEFAULT \'draft\',\n        total INTEGER DEFAULT 0, sent INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, skipped INTEGER DEFAULT 0,\n        created_at BIGINT, audience TEXT DEFAULT \'all\')""",\n    """CREATE TABLE IF NOT EXISTS audit_log(\n        id {PK}, admin_id BIGINT, action TEXT, details TEXT, at BIGINT)""",\n    """CREATE TABLE IF NOT EXISTS ratings(\n        user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        stars INTEGER NOT NULL, created_at BIGINT, PRIMARY KEY(user_id, movie_id))""",\n    """CREATE TABLE IF NOT EXISTS promo_codes(\n        code TEXT PRIMARY KEY, days INTEGER NOT NULL, max_uses INTEGER NOT NULL, used INTEGER DEFAULT 0,\n        active INTEGER DEFAULT 1, created_at BIGINT)""",\n    """CREATE TABLE IF NOT EXISTS promo_uses(\n        code TEXT NOT NULL REFERENCES promo_codes(code) ON DELETE CASCADE,\n        user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, used_at BIGINT,\n        PRIMARY KEY(code, user_id))""",\n    """CREATE TABLE IF NOT EXISTS tickets(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL,\n        movie_id INTEGER, text TEXT, status TEXT DEFAULT \'open\', created_at BIGINT, closed_by BIGINT)""",\n    "CREATE INDEX IF NOT EXISTS ix_tickets_status ON tickets(status)",\n    """CREATE TABLE IF NOT EXISTS channels(\n        chat_id BIGINT PRIMARY KEY, title TEXT, link TEXT, enabled INTEGER DEFAULT 1, created_at BIGINT)""",\n    "CREATE TABLE IF NOT EXISTS campaign_claims(user_id BIGINT PRIMARY KEY, name TEXT, days INTEGER, at BIGINT)",\n    """CREATE TABLE IF NOT EXISTS watchlist(\n        user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        created_at BIGINT, PRIMARY KEY(user_id, movie_id))""",\n    """CREATE TABLE IF NOT EXISTS series_subs(\n        user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        series_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        created_at BIGINT, PRIMARY KEY(user_id, series_id))""",\n    """CREATE TABLE IF NOT EXISTS reviews(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,\n        text TEXT NOT NULL, hidden INTEGER DEFAULT 0, created_at BIGINT, UNIQUE(user_id, movie_id))""",\n    """CREATE TABLE IF NOT EXISTS search_history(\n        id {PK}, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, query TEXT NOT NULL, at BIGINT)""",\n    "CREATE INDEX IF NOT EXISTS ix_reviews_movie ON reviews(movie_id, hidden)",\n    "CREATE INDEX IF NOT EXISTS ix_search_user ON search_history(user_id, id)",\n    "CREATE INDEX IF NOT EXISTS ix_watchlist_user ON watchlist(user_id, created_at)",\n    "CREATE INDEX IF NOT EXISTS ix_subs_series ON series_subs(series_id)",\n    "CREATE INDEX IF NOT EXISTS ix_history_time ON history(watched_at)",\n    "CREATE INDEX IF NOT EXISTS ix_users_joined ON users(joined_at)",\n    "CREATE TABLE IF NOT EXISTS user_state(user_id BIGINT PRIMARY KEY, state TEXT, data TEXT)",\n    "CREATE TABLE IF NOT EXISTS processed_updates(update_id BIGINT PRIMARY KEY, at BIGINT)",\n    "CREATE INDEX IF NOT EXISTS ix_movies_title ON movies(title)",\n    "CREATE INDEX IF NOT EXISTS ix_movies_kind_created ON movies(kind, created_at)",\n    "CREATE INDEX IF NOT EXISTS ix_episodes_series ON episodes(series_id)",\n    "CREATE INDEX IF NOT EXISTS ix_history_user ON history(user_id, watched_at)",\n    "CREATE INDEX IF NOT EXISTS ix_payments_user ON payments(user_id)",\n    "CREATE INDEX IF NOT EXISTS ix_payments_status ON payments(status)",\n    "CREATE INDEX IF NOT EXISTS ix_users_premium ON users(premium_until)",\n]\n\n\ndef init(url=None):\n    """DB manzilini o\'rnatadi (test uchun qayta chaqirish mumkin)."""\n    global IS_PG, _url\n    url = url or cfg.database_url\n    if url.startswith("postgres://"):\n        url = "postgresql://" + url[len("postgres://"):]\n    IS_PG = url.startswith("postgresql")\n    _url = url\n    reset_conn()\n    for h in _init_hooks:\n        h()\n\n\ndef _connect():\n    if IS_PG:\n        import psycopg2\n        import psycopg2.extras\n        return psycopg2.connect(_url, cursor_factory=psycopg2.extras.RealDictCursor)\n    path = _url.replace("sqlite:///", "", 1) if _url.startswith("sqlite:///") else _url\n    con = sqlite3.connect(path, timeout=30)\n    con.row_factory = sqlite3.Row\n    con.execute("PRAGMA foreign_keys=ON")\n    for pragma in ("journal_mode=WAL", "synchronous=NORMAL", "temp_store=MEMORY", "cache_size=-8000"):\n        try:\n            con.execute("PRAGMA " + pragma)\n        except sqlite3.DatabaseError:\n            pass\n    return con\n\n\ndef reset_conn():\n    c = getattr(_tl, "conn", None)\n    _tl.conn = None\n    if c is not None:\n        try:\n            c.close()\n        except Exception:\n            pass\n\n\ndef _conn():\n    c = getattr(_tl, "conn", None)\n    if c is not None and getattr(_tl, "url", None) == _url and not (IS_PG and getattr(c, "closed", 0)):\n        return c\n    reset_conn()\n    c = _connect()\n    _tl.conn, _tl.url = c, _url\n    return c\n\n\nclass Tx:\n    def __init__(self, conn):\n        self.conn = conn\n\n    def _s(self, sql):\n        return sql.replace("?", "%s") if IS_PG else sql\n\n    def _run(self, sql, args):\n        cur = self.conn.cursor()\n        cur.execute(self._s(sql), tuple(args))\n        return cur\n\n    def q(self, sql, args=()):\n        cur = self._run(sql, args)\n        return [dict(r) for r in cur.fetchall()]\n\n    def one(self, sql, args=()):\n        rows = self.q(sql, args)\n        return rows[0] if rows else None\n\n    def exec(self, sql, args=()):\n        return self._run(sql, args).rowcount\n\n    def insert(self, sql, args=()):\n        if IS_PG:\n            cur = self._run(sql + " RETURNING id", args)\n            return cur.fetchone()["id"]\n        return self._run(sql, args).lastrowid  # eski SQLite versiyalarida RETURNING yo\'q\n\n\n@contextlib.contextmanager\ndef tx():\n    conn = _conn()\n    try:\n        yield Tx(conn)\n        conn.commit()\n    except BaseException:\n        try:\n            conn.rollback()\n        except Exception:\n            reset_conn()\n        if IS_PG and getattr(conn, "closed", 0):\n            reset_conn()\n        raise\n\n\ndef q(sql, args=()):\n    with tx() as t:\n        return t.q(sql, args)\n\n\ndef one(sql, args=()):\n    with tx() as t:\n        return t.one(sql, args)\n\n\ndef execute(sql, args=()):\n    with tx() as t:\n        return t.exec(sql, args)\n\n\ndef _backup_incompatible_sqlite():\n    """Eski bot (kino_bot.py) bazasi bilan to\'qnashuvni oldini oladi: tuzilma mos kelmasa fayl zaxiralanadi."""\n    import os\n    import time\n    if IS_PG:\n        return None\n    path = _url.replace("sqlite:///", "", 1) if _url.startswith("sqlite:///") else _url\n    if not os.path.isfile(path):\n        return None\n    try:\n        con = sqlite3.connect(path)\n        mcols = [r[1] for r in con.execute("PRAGMA table_info(movies)")]\n        ucols = [r[1] for r in con.execute("PRAGMA table_info(users)")]\n        con.close()\n    except sqlite3.DatabaseError:\n        mcols, ucols = ["?"], ["?"]\n    bad = (mcols and "kind" not in mcols) or (ucols and "first_name" not in ucols)\n    if not bad:\n        return None\n    new = "%s.eski_%d" % (path, int(time.time()))\n    reset_conn()\n    os.replace(path, new)\n    for ext in ("-wal", "-shm"):\n        if os.path.exists(path + ext):\n            os.remove(path + ext)\n    print("Eski baza tuzilmasi mos emas -> zaxiralandi:", new)\n    return new\n\n\ndef _add_column(t, table, col, decl):\n    if IS_PG:\n        t.exec(f"ALTER TABLE {table} ADD COLUMN IF NOT EXISTS {col} {decl}")\n    elif col not in [r["name"] for r in t.q(f"PRAGMA table_info({table})")]:\n        t.exec(f"ALTER TABLE {table} ADD COLUMN {col} {decl}")\n\n\ndef sqlite_path():\n    if IS_PG:\n        return None\n    return _url.replace("sqlite:///", "", 1) if _url.startswith("sqlite:///") else _url\n\n\ndef init_schema():\n    _backup_incompatible_sqlite()\n    pk = "SERIAL PRIMARY KEY" if IS_PG else "INTEGER PRIMARY KEY AUTOINCREMENT"\n    with _lock, tx() as t:\n        for stmt in _DDL:\n            t.exec(stmt.replace("{PK}", pk))\n        for table, col, decl in (("users", "notify_new", "INTEGER DEFAULT 0"), ("users", "streak", "INTEGER DEFAULT 0"),\n                                 ("users", "last_checkin", "TEXT"), ("users", "blocked_until", "BIGINT DEFAULT 0"),\n                                 ("users", "remind_off", "INTEGER DEFAULT 0"), ("movies", "trailer_url", "TEXT"),\n                                 ("movies", "featured", "INTEGER DEFAULT 0"), ("broadcasts", "audience", "TEXT DEFAULT \'all\'")):\n            _add_column(t, table, col, decl)\n        t.exec("INSERT INTO settings(key,value) VALUES(\'schema_version\',?) "\n               "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(SCHEMA_VERSION),))\n\n\ndef drop_all_for_tests():\n    for name in ("campaign_claims", "search_history", "reviews", "series_subs", "watchlist", "channels", "tickets", "promo_uses", "promo_codes", "ratings", "history", "favorites", "video_variants", "episodes", "subscriptions", "payments",\n                 "movies", "users", "admins", "settings", "sponsors", "broadcasts", "audit_log",\n                 "user_state", "processed_updates"):\n        execute("DROP TABLE IF EXISTS " + name)\n'
